// План specs/gps-workflow.md 3.1 (кейс .qa/tests/gps-workflow/GW-05). PROD, gps (компания «בדיקה»), десктоп, EN.
// @prod-safe: только просмотр. Данные QA 12.11: однострочное SMS «QA test 1 Desc: Car Lockout Address: 400 Broad St, Seattle, WA 98109»
// (авто-правило → JOB-0007 на QA-Tech Auto). Новое SMS автотест прислать не может — разбор свежего сообщения только вручную (GW-06).
import { test, expect } from '../../fixtures';
import { ROLE, prepare, openGpsAll, openMessage, openJobFromDialog } from './gps-helpers';

const MESSAGE = /^QA-John Miller\b.*Seattle, WA 98109/; // не путать с +972537312995 (Nov 2, старое, «Seattle, WA 98109, USA»)
const TEXT = 'QA test 1 Desc: Car Lockout Address: 400 Broad St, Seattle, WA 98109';
const FULL = '400 Broad St, Seattle, WA 98109, USA';

test.describe('GPS Workflow — адрес из однострочного сообщения (#324ddc)', () => {
  test('One-line message "… Address: 400 Broad St, Seattle, WA 98109": full street address in message and in its job #324ddc @desktop @prod-safe', async ({ asUser }) => {
    test.setTimeout(120_000);
    const page = await asUser(ROLE);
    await prepare(page);

    await openGpsAll(page);
    const dialog = await openMessage(page, MESSAGE);
    await expect(dialog.getByText(TEXT, { exact: true }), 'текст сообщения одной строкой').toBeVisible();
    await expect(dialog.getByText(FULL, { exact: true }), 'адрес с улицей в сообщении').toBeVisible();

    await openJobFromDialog(page, dialog);
    await expect(page.getByText('#JOB-0007', { exact: true })).toBeVisible({ timeout: 30_000 });
    await expect(page.getByRole('textbox', { name: 'Address' })).toHaveValue(FULL);
    await expect(page.getByRole('textbox', { name: 'City' })).toHaveValue('Seattle');
    await expect(page.getByRole('textbox', { name: 'Region/State' })).toHaveValue('WA');
    await expect(page.getByRole('textbox', { name: 'ZIP Code' })).toHaveValue('98109');
  });
});
